package com.novalang.bukkit.types.event;
import com.novalang.bukkit.Requires; import com.novalang.bukkit.types.value.NovaTypeSupport; import com.novalang.runtime.host.JavaTypes; import org.bukkit.entity.ArmorStand; import org.bukkit.event.player.PlayerArmorStandManipulateEvent; import org.bukkit.inventory.EquipmentSlot; import org.bukkit.inventory.ItemStack;
@Requires(classes = {"org.bukkit.event.player.PlayerArmorStandManipulateEvent"}) public final class NovaPlayerArmorStandManipulateEvent { private NovaPlayerArmorStandManipulateEvent() { } public static void register(JavaTypes.Builder b){b.extension(PlayerArmorStandManipulateEvent.class,"playerItem",f->f.returns(ItemStack.class).invoke(a->event(a).getPlayerItem()));b.extension(PlayerArmorStandManipulateEvent.class,"armorStandItem",f->f.returns(ItemStack.class).invoke(a->event(a).getArmorStandItem()));b.extension(PlayerArmorStandManipulateEvent.class,"slot",f->f.returns(EquipmentSlot.class).invoke(a->event(a).getSlot()));b.extension(PlayerArmorStandManipulateEvent.class,"hand",f->f.returns(EquipmentSlot.class).invoke(a->event(a).getHand()));b.extension(PlayerArmorStandManipulateEvent.class,"rightClicked",f->f.returns(ArmorStand.class).invoke(a->event(a).getRightClicked()));}private static PlayerArmorStandManipulateEvent event(Object[] a){return NovaTypeSupport.argument(a,0,PlayerArmorStandManipulateEvent.class);}}
